record.field:
{
    "type": "object",
    "properties": {
        "search": {
            "type": "string",
            "description": "Filter module names by substring."
        },
        "state": {
            "type": "string",
            "description": "Filter by state. Default: 'installed'.",
            "enum": ["installed", "uninstalled", "to upgrade", "to install"],
            "default": "installed"
        }
    }
}

{
    "type": "object",
    "properties": {
        "search": {
            "type": "string",
            "description": "Filter model names by substring (case-insensitive). Examples: 'sale', 'partner', 'account', 'stock', 'project'."
        },
        "limit": {
            "type": "integer",
            "description": "Maximum number of models to return.",
            "default": 100
        }
    }
}

{
    "type": "object",
    "properties": {
        "model": {
            "type": "string",
            "description": "Technical model name (e.g. 'res.partner')."
        },
        "domain": {
            "type": "array",
            "description": "Odoo domain filter. Examples: [['is_company','=',true]], ['|',['email','ilike','@gmail'],['email','ilike','@outlook']], [['state','=','sale'],['date_order','>=','2024-01-01']].",
            "default": []
        },
        "fields": {
            "type": "array",
            "items": {"type": "string"},
            "description": "Field names to return. ALWAYS specify this to avoid returning all fields. Example: ['name','email','phone','state']."
        },
        "limit": {
            "type": "integer",
            "description": "Maximum records to return. Use small values (10-50) for exploration, larger (up to 500) when you need bulk data.",
            "default": 80
        },
        "offset": {
            "type": "integer",
            "description": "Number of records to skip for pagination.",
            "default": 0
        },
        "order": {
            "type": "string",
            "description": "Sort order. Example: 'create_date desc', 'name asc, id desc'."
        }
    },
    "required": ["model"]
}

{
    "type": "object",
    "properties": {
        "model": {
            "type": "string",
            "description": "Technical model name."
        },
        "ids": {
            "type": "array",
            "items": {"type": "integer"},
            "description": "Record IDs to read."
        },
        "fields": {
            "type": "array",
            "items": {"type": "string"},
            "description": "Field names to return. ALWAYS specify this."
        }
    },
    "required": ["model", "ids"]
}

{
    "type": "object",
    "properties": {
        "model": {
            "type": "string",
            "description": "Technical model name."
        },
        "domain": {
            "type": "array",
            "description": "Odoo domain filter. Same syntax as search_read.",
            "default": []
        }
    },
    "required": ["model"]
}

{
    "type": "object",
    "properties": {
        "model": {
            "type": "string",
            "description": "Technical model name."
        },
        "values": {
            "type": "object",
            "description": "Field values for the new record. Example: {'name': 'John', 'email': 'john@example.com', 'company_id': 1}."
        }
    },
    "required": ["model", "values"]
}

{
    "type": "object",
    "properties": {
        "model": {
            "type": "string",
            "description": "Technical model name."
        },
        "ids": {
            "type": "array",
            "items": {"type": "integer"},
            "description": "Record IDs to update."
        },
        "values": {
            "type": "object",
            "description": "Field values to change. Only include fields you want to modify."
        }
    },
    "required": ["model", "ids", "values"]
}

{
    "type": "object",
    "properties": {
        "model": {
            "type": "string",
            "description": "Technical model name."
        },
        "ids": {
            "type": "array",
            "items": {"type": "integer"},
            "description": "Record IDs to permanently delete."
        }
    },
    "required": ["model", "ids"]
}

{
    "type": "object",
    "properties": {
        "model": {
            "type": "string",
            "description": "Technical model name."
        },
        "domain": {
            "type": "array",
            "description": "Filter domain. Same syntax as search_read.",
            "default": []
        },
        "fields": {
            "type": "array",
            "items": {"type": "string"},
            "description": "Fields to aggregate. Include the groupby field and any numeric fields to sum/avg. Example: ['state', 'amount_total']."
        },
        "groupby": {
            "type": "array",
            "items": {"type": "string"},
            "description": "Fields to group by. Examples: ['state'], ['partner_id', 'state'], ['date_order:month']."
        },
        "limit": {
            "type": "integer",
            "description": "Maximum number of groups to return."
        },
        "order": {
            "type": "string",
            "description": "Sort order for groups. Example: 'amount_total desc'."
        },
        "lazy": {
            "type": "boolean",
            "description": "If true (default), group one level at a time. If false, group by all fields at once.",
            "default": true
        }
    },
    "required": ["model", "fields", "groupby"]
}

{
    "type": "object",
    "properties": {
        "model": {
            "type": "string",
            "description": "Technical model name (e.g. 'sale.order')."
        },
        "id": {
            "type": "integer",
            "description": "The record ID to get messages for."
        },
        "limit": {
            "type": "integer",
            "description": "Maximum number of messages to return (newest first).",
            "default": 20
        }
    },
    "required": ["model", "id"]
}

{
    "type": "object",
    "properties": {
        "model": {
            "type": "string",
            "description": "Technical model name."
        },
        "id": {
            "type": "integer",
            "description": "The record ID to post the message on."
        },
        "body": {
            "type": "string",
            "description": "The message content (can contain HTML)."
        },
        "type": {
            "type": "string",
            "description": "Message type: 'comment' (visible to followers) or 'note' (internal note).",
            "enum": ["comment", "note"],
            "default": "comment"
        }
    },
    "required": ["model", "id", "body"]
}

{
    "type": "object",
    "properties": {
        "model": {
            "type": "string",
            "description": "Technical model name."
        },
        "method": {
            "type": "string",
            "description": "Public method name (e.g. 'action_confirm', 'action_post', 'message_post')."
        },
        "ids": {
            "type": "array",
            "items": {"type": "integer"},
            "description": "Record IDs to call the method on. Omit for @api.model methods."
        },
        "args": {
            "type": "array",
            "description": "Positional arguments to pass to the method."
        },
        "kwargs": {
            "type": "object",
            "description": "Keyword arguments to pass to the method."
        }
    },
    "required": ["model", "method"]
}
